// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        // current owner (this test contract) hands ownership to fuzzed newOwner
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);

        // fuzzed caller attempts an onlyOwner action
        bool ok;
        vm.prank(caller);
        try c.setRewardDistributor(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // a successful onlyOwner call must have been made by the current owner
            assertTrue(caller == c.owner());
        } else {
            // a reverted onlyOwner call must leave state untouched
            assertTrue(c.rewardDistributor() != caller);
        }
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
